if.script:
for (Map module in (course.modules ?: [])) {
    Map state = states.moduleStates[module.moduleId] ?: [:]
    module.dueDate = state.dueDate
    module.overdue = state.overdue
    module.locked = state.locked
    if (state.locked) {
        module.slides = null
        module.videoUrl = null
        module.exercises = (module.exercises ?: []).collect { it + [prompt: null] }
        module.lessons = (module.lessons ?: []).collect { Map l ->
            l.findAll { k, v -> !(k in ['content', 'keyPoints', 'videoUrl']) } }
    }
}

def slurper = new groovy.json.JsonSlurper()
def completedList = slurper.parseText(progressEntity.completedLessons ?: '[]') as List
if (completed && !completedList.contains(lessonId)) {
    completedList.add(lessonId)
} else if (!completed) {
    completedList.remove(lessonId)
}
context.completedLessonsJson = groovy.json.JsonOutput.toJson(completedList)
context.progressPercent = totalLessons > 0 ? ((completedList.size() * 100) / totalLessons) as Integer : 0
context.isCompleted = completedList.size() == totalLessons
